{"cards": [{"node_code": "N_8b46868b711d9463", "definition": "研究公路旅客运输的组织技术，涵盖客运班线规划、班次安排、客运站服务流程、票务管理、旅客服务标准及特殊旅客（如老幼病残）的运输保障。", "boundary": "本节点聚焦于“旅客”运输的业务流程与服务技术。边界在于区分“货物运输”（侧重货物装卸、包装、仓储及货运单据，归入货物运输及商务工作）与“行车组织”（侧重车辆运行时刻、线路调度等通用技术，归入行车组织）。若内容涉及客运车辆本身的机械性能，归入汽车工程；若涉及客运票价制定与市场策略，归入运输经济。", "includes": ["客运班线布局、时刻表编制及客流预测", "客运站（场）旅客服务流程、候车环境及票务系统操作", "旅客安全服务、投诉处理及特殊群体运输保障"], "excludes": ["货物运输的装卸、包装及货运单据处理（归入货物运输及商务工作）", "车辆运行时刻表编制及线路调度算法（归入行车组织）", "客运票价制定、成本核算及市场经营策略（归入陆路、公路运输经济）"], "sibling_distinctions": [{"other_code": "N_67a9b1cc28a3a542", "rule": "本节点针对“人”的运输服务与流程；货物运输及商务工作针对“物”的装卸、保管及货运合同处理。"}, {"other_code": "N_233746aee3bc7b68", "rule": "本节点侧重客运特有的服务环节（如售票、候车、旅客引导）；行车组织侧重车辆运行的通用技术（如发车间隔、线路选择）。"}], "cross_boundary_rule": "若内容涉及“定制客运”或“网约车”，侧重服务流程与乘客体验归本节点；若侧重车辆调度算法或平台技术架构，可关联行车组织或电子计算机应用。"}, {"node_code": "N_b4cf3112bf46f768", "definition": "研究在特殊地理、气候或社会环境下（如高原、高寒、沙漠、山区、边境、灾区）进行汽车运输的组织技术、安全保障措施及适应性管理方法。", "boundary": "本节点聚焦于“特殊环境”对运输组织的影响及应对技术。边界在于区分“一般地区运输”（常规路况下的运营，归入其他运营技术节点）与“车辆改装”（针对特殊环境的车辆硬件改造，归入汽车工程）。若内容涉及特殊地区道路建设，归入道路工程；若涉及特殊地区运输的经济效益分析，归入运输经济。", "includes": ["高原、高寒、沙漠、山区等特殊路况下的行车组织与调度", "特殊环境下的车辆技术保障、驾驶员适应性管理及安全预案", "边境、灾区、军事等特殊任务背景下的汽车运输组织"], "excludes": ["特殊地区道路、桥梁等基础设施的建设与维护（归入道路工程）", "针对特殊环境的车辆底盘、发动机等硬件改装技术（归入汽车工程）", "特殊地区运输的成本效益分析与政策评估（归入陆路、公路运输经济）"], "sibling_distinctions": [{"other_code": "N_8b46868b711d9463", "rule": "本节点强调“环境特殊性”对运输组织的制约与应对；旅客运输侧重常规环境下的客运服务流程。"}, {"other_code": "N_233746aee3bc7b68", "rule": "本节点包含特殊环境下的行车组织，但核心在于环境适应性；行车组织侧重常规路网下的运行效率与时刻表优化。"}], "cross_boundary_rule": "若内容涉及“特殊地区道路养护”，主挂载道路工程；若涉及“特殊地区运输组织与安全”，主挂载本节点。"}, {"node_code": "N_6df50a3fe251171c", "definition": "研究汽车与其他运输方式（如铁路、水运、航空）或不同汽车运输企业之间的联合运输组织技术，包括衔接流程、单证流转、责任划分及信息共享机制。", "boundary": "本节点聚焦于“联运”的组织协调与技术衔接。边界在于区分“单一方式运输”（仅涉及公路运输内部组织，归入行车组织或客货运输）与“综合运输规划”（宏观层面的多式联运网络规划，若树中有综合运输节点则归入，否则视具体侧重）。若内容涉及联运中的车辆机械故障处理，归入汽车工程；若涉及联运价格体系，归入运输经济。", "includes": ["公铁、公水、公空联运的衔接组织与流程设计", "联运单证（如提单、运单）的流转、标准化及责任界定", "多式联运中的信息共享、货物追踪及协同调度技术"], "excludes": ["单一公路运输内部的行车组织与调度（归入行车组织）", "联运涉及的宏观政策制定、运价体系及市场准入（归入陆路、公路运输经济）", "联运中使用的具体通信设备或软件代码实现（归入电子计算机应用）"], "sibling_distinctions": [{"other_code": "N_233746aee3bc7b68", "rule": "本节点侧重跨方式或跨企业的“衔接”与“协调”；行车组织侧重单一运输方式内部的运行效率。"}, {"other_code": "N_67a9b1cc28a3a542", "rule": "本节点涉及联运中的商务单证与责任划分；货物运输及商务工作侧重单一公路货运的装卸、保管及基础商务流程。"}], "cross_boundary_rule": "若内容涉及“多式联运信息平台”，侧重平台技术架构归电子计算机应用；侧重联运业务流程与规则归本节点。"}]}
